{
  "driver_archetypes": [
    {
      "id": "car_std",
      "base_vclass": "passenger",
      "share": 1.0,
      "params": {
        "tau": 0.95,
        "minGap": 2.0,
        "accel": 2.6,
        "decel": 4.5,
        "sigma": 0.5,
        "impatience": 0.0
      },
      "rationale": "Adjusts car discharge headway (M1/car) slightly down from 0.63s to ~0.35s by reducing tau to 0.95s while keeping near-default accel/decel; maintains low red-running/early-start shares (M3/share/car, M2/early/car) via impatience=0."
    },
    {
      "id": "moto_norm",
      "base_vclass": "motorcycle",
      "share": 0.55,
      "params": {
        "tau": 0.6,
        "minGap": 0.7,
        "accel": 4.0,
        "decel": 8.0,
        "sigma": 0.3,
        "minGapLat": 0.35,
        "maxSpeedLat": 1.5,
        "latAlignment": "compact",
        "lcSublane": 2.5,
        "lcPushy": 0.6,
        "lcMaxSpeedLatStanding": 1.0,
        "impatience": 0.3,
        "jmDriveAfterRedTime": 4.0,
        "jmDriveRedSpeed": 6.0
      },
      "rationale": "Increases red-running probability and reduces minGap/minGapLat/tau to increase motorcycle overcrowding at the stop line, targeting M4/overshoot_share (0.62) and M1/moto headway (0.30s); jmDriveAfterRedTime=4s allows a share to run red towards M3/share/moto (0.098)."
    },
    {
      "id": "moto_slow",
      "base_vclass": "motorcycle",
      "share": 0.15,
      "params": {
        "tau": 0.9,
        "minGap": 0.9,
        "accel": 3.0,
        "decel": 8.0,
        "sigma": 0.4,
        "speedFactor": 0.75,
        "speedDev": 0.1,
        "latAlignment": "center",
        "impatience": 0.1
      },
      "rationale": "Slow riders (speedFactor=0.75) keep the lane centre to increase M6/approach times towards observed values (e.g., s/moto ~36s); their presence contributes to M4/lat_moto (mean lateral pos)."
    },
    {
      "id": "moto_seek",
      "base_vclass": "custom1",
      "share": 0.30,
      "params": {
        "tau": 0.65,
        "minGap": 0.75,
        "accel": 4.0,
        "decel": 8.0,
        "sigma": 0.35,
        "minGapLat": 0.35,
        "maxSpeedLat": 1.6,
        "latAlignment": "compact",
        "lcSublane": 2.5,
        "lcPushy": 0.7,
        "lcMaxSpeedLatStanding": 1.2,
        "impatience": 0.4,
        "jmDriveAfterRedTime": 4.0,
        "jmDriveRedSpeed": 6.0
      },
      "rationale": "Space-seeking riders (custom1) with higher impatience and pushiness target wrong-lane/sidewalk choices; share 0.30 scales per-rider probabilities to match M8/moto wrong-lane share (0.249) and F2 sidewalk shares."
    },
    {
      "id": "moto_viol",
      "base_vclass": "custom1",
      "share": 1.0,
      "params": {
        "tau": 0.7,
        "minGap": 0.9,
        "accel": 4.0,
        "decel": 8.0,
        "sigma": 0.35,
        "impatience": 0.6,
        "jmTimegapMinor": 1.5
      },
      "rationale": "Illegal-left riders wait in the box; increasing jmTimegapMinor to 1.5s from the default 1.0s increases the hold time after the opposing green ends, targeting M7a/n_waiting (5.59 veh) and M7b/clear_lag (5.46s)."
    }
  ],
  "traci_rules": [
    {
      "rule_type": "early_start",
      "applies_to": ["moto_norm", "moto_slow", "moto_seek"],
      "params": {
        "t_before_green": 8.0,
        "p": 0.14,
        "v_max": 2.5
      },
      "rationale": "Targets M2/early/moto (0.1302 share in last 10s of red): p=0.14 approximates the observed share; v_max=2.5 m/s creates a short delay between green onset and crossing, affecting M2/first_delay (2.83s)."
    },
    {
      "rule_type": "early_start",
      "applies_to": ["car_std"],
      "params": {
        "t_before_green": 6.0,
        "p": 0.011,
        "v_max": 2.0
      },
      "rationale": "Targets M2/early/car (0.0111 share): p set to observed car early-start share; low v_max keeps cars compliant."
    },
    {
      "rule_type": "swarm_red_running",
      "applies_to": ["moto_norm", "moto_slow", "moto_seek"],
      "params": {
        "p0": 0.12,
        "k": 0.08,
        "p_max": 0.5,
        "dt": 10.0
      },
      "rationale": "Targets M3/share/moto (0.098) and M3/per_cycle (3.9 veh/cycle): higher base p0=0.12 plus a strong swarm effect k=0.08 raises the overall red-running share to ~0.1 while maintaining overdispersion (var/mean ~1.14)."
    },
    {
      "rule_type": "swarm_red_running",
      "applies_to": ["car_std"],
      "params": {
        "p0": 0.004,
        "k": 0.0,
        "p_max": 0.01,
        "dt": 10.0
      },
      "rationale": "Targets M3/share/car (0.0041): p0 set to observed share and no swarm effect keeps car red running rare."
    },
    {
      "rule_type": "queue_space_seeking",
      "applies_to": ["moto_seek"],
      "params": {
        "q": 8.0,
        "t_g_s": 7.0,
        "est_noise": 0.4,
        "p_wrong_lane": 0.45,
        "p_right_lane": 0.0,
        "p_sidewalk": 0.12,
        "v_creep": 3.5,
        "merge_zone_m": 12.0
      },
      "rationale": "Lower queue trigger q=8m ensures the rule fires in short queues (M10b/M9c ~15m); p_wrong_lane=0.45 targets F2/p/wrong_lane shares (~0.2 at low-q, rising to ~0.45 at higher-q when combined with other factors); p_sidewalk=0.12 targets M10a (0.56 veh/cycle) and F2 sidewalk shares; t_g_s=7s implements the green-check logic from the prompt."
    },
    {
      "rule_type": "illegal_left_box",
      "applies_to": ["moto_viol"],
      "params": {
        "release_lag_s": 1.5
      },
      "rationale": "Targets M7a/release_time (2.78s) and M7b/clear_lag (5.46s): release_lag_s=1.5s adds a moderate hold on top of SUMO's native release to match the observed exit timing after the opposing green ends."
    },
    {
      "rule_type": "slow_lane_center",
      "applies_to": ["moto_slow"],
      "params": {
        "lat_offset": 0.05
      },
      "rationale": "Slow motorcycles keep near the lane centre (offset=0.05m) to support M6/approach times and avoid excessive lateral spread that would distort M4/lat_moto."
    }
  ],
  "description": "Revised spec lowering S: car headway fixed via tau reduction; motorcycle red-running and early-start calibrated to match shares (~0.1 for moto, ~0.004 for car); queue-space-seeking probabilities adjusted to hit wrong-lane/sidewalk targets at observed queue lengths; illegal-left hold time increased to fix box-clear lag."
}
